const audioResponses = $input.all();
const preparedTracks = $('Prepare audio deliveries').all();

function escapeRichHtml(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('\"', '&quot;')
    .replaceAll("'", '&apos;');
}

function formatLyricLine(line) {
  const escaped = escapeRichHtml(line);

  return escaped.replace(
    /^(\[(?:\d{1,2}:)?\d{1,2}:\d{2}(?:[.:]\d{1,3})?\])/,
    '<b>$1</b>',
  );
}

function splitLyrics(rawLyrics) {
  const lyrics = String(rawLyrics ?? '')
    .replace(/\r/g, '')
    .trim();

  if (!lyrics) {
    return [];
  }

  const maximumFormattedLength = 26000;
  const chunks = [];
  let current = '';

  function formattedLength(value) {
    return value
      .split('\n')
      .map(formatLyricLine)
      .join('<br>')
      .length;
  }

  function pushCurrent() {
    if (current.trim()) {
      chunks.push(current.trim());
      current = '';
    }
  }

  for (const line of lyrics.split('\n')) {
    const candidate = current ? `${current}\n${line}` : line;

    if (formattedLength(candidate) <= maximumFormattedLength) {
      current = candidate;
      continue;
    }

    pushCurrent();

    if (formattedLength(line) <= maximumFormattedLength) {
      current = line;
      continue;
    }

    for (const word of line.split(/\s+/)) {
      const wordCandidate = current ? `${current} ${word}` : word;

      if (formattedLength(wordCandidate) <= maximumFormattedLength) {
        current = wordCandidate;
      } else {
        pushCurrent();
        current = word;
      }
    }
  }

  pushCurrent();
  return chunks;
}

function encodePayload(payload) {
  return Buffer
    .from(JSON.stringify(payload), 'utf8')
    .toString('base64');
}

const output = [];

for (let index = 0; index < audioResponses.length; index += 1) {
  const response = audioResponses[index]?.json ?? {};
  const prepared = preparedTracks[index]?.json ?? {};
  const audioMessageId =
    response?.result?.message_id ??
    response?.message_id ??
    null;
  const chunks = splitLyrics(prepared.lyrics);

  if (!chunks.length || !audioMessageId) {
    output.push({
      json: {
        jobDirectory: prepared.jobDirectory ?? '',
        richPayloadB64: '',
      },
    });
    continue;
  }

  chunks.forEach((chunk, chunkIndex) => {
    const title = escapeRichHtml(prepared.title || 'Unknown track');
    const artist = prepared.artist
      ? `<p><i>${escapeRichHtml(prepared.artist)}</i></p>`
      : '';
    const part = chunks.length > 1
      ? ` · Part ${chunkIndex + 1}/${chunks.length}`
      : '';
    const formattedLyrics = chunk
      .split('\n')
      .map(formatLyricLine)
      .join('<br>');
    const summary = prepared.lyricsSynced
      ? `Synced lyrics${part}`
      : `Lyrics${part}`;
    const html = [
      `<h3>🎼 ${title}</h3>`,
      artist,
      '<details>',
      `<summary>${escapeRichHtml(summary)}</summary>`,
      `<blockquote>${formattedLyrics}</blockquote>`,
      '</details>',
      `<footer>Spotipy · ${escapeRichHtml(summary)}</footer>`,
    ]
      .filter(Boolean)
      .join('');

    output.push({
      json: {
        jobDirectory: prepared.jobDirectory ?? '',
        richPayloadB64: encodePayload({
          chatId: String(prepared.chatId),
          html,
          replyToMessageId: audioMessageId,
        }),
      },
    });
  });
}

return output;
